def count_colors_with_one_between(arr: list[int]) -> int:
    res = 0
    unique_colors = set(arr)
    for color in unique_colors:
        first_index = arr.index(color)
        second_index = arr.index(color, first_index + 1)
        if second_index - first_index == 2:
            res += 1
    return res
